{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Octreotide, a cyclic octapeptide, had absolute oral bioavailability of 0.6 ± 0.4% in healthy humans after an 8 mg capsule; this direct human F measurement for a peptide drug supports low oral bioavailability for the similarly peptide-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "GHRP-6, a hexapeptide, showed systemic availability of ~0.3% after oral administration in humans, requiring extremely high oral doses; this supports low F for peptide drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, a peptidomimetic renin inhibitor, had 0.5% oral bioavailability in humans at 40 mg p.o.; this supports low F for peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Plecanatide, a peptide, exhibited negligible systemic availability after oral dosing in humans, with plasma levels below the limit of quantitation; supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Macimorelin, a small peptidomimetic, showed good oral bioavailability in patients, but its much smaller size and lower polarity make this result poorly transferable to the large, highly polar query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an extremely large, highly polar, fully ionized peptide (MW >4100 Da, TPSA >1600 Å², logD -19.4). Direct human oral bioavailability data for related peptide/peptidomimetic drugs (octreotide 0.3-0.6%, GHRP-6 ~0.3%, enalkiren 0.5%, plecanatide negligible) all show F <20%, strongly supporting low oral bioavailability. The only positive example (macimorelin) is a much smaller molecule and not transferable.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "One supplied record (C12) appears internally inconsistent (paliperidone result attached to a peptide SMILES) and was not weighted.",
    "Potential active uptake or prodrug behavior cannot be fully excluded, though unlikely for a molecule of this size and polarity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

